-- Catálogo bilíngue 8/10, parte 4/4 (500 palavras). Execute as quatro partes em ordem.
-- Reexecutável: atualiza definition_pt e example_pt de palavras já importadas.
begin;
do $$ begin if exists (select 1 from (select unnest(array['arts', 'business', 'food', 'general-vocabulary', 'health', 'law', 'politics', 'science', 'sports', 'technical', 'technology']) as slug) required left join public.vocabulary_categories c using (slug) where c.id is null) then raise exception 'Categorias do catálogo ausentes'; end if; end $$;
insert into public.vocabulary_words (word,translation,definition_en,definition_pt,example_en,example_pt,cefr_level,word_type,category_id,frequency_rank)
select v.word,v.translation,v.definition_en,v.definition_pt,v.example_en,v.example_pt,v.cefr_level,v.word_type,c.id,v.frequency_rank
from jsonb_to_recordset($catalog$
[
{"word":"allograph","translation":"alógrafo","definition_en":"A variant form of a written character or letter, such as different fonts or handwriting styles representing the same letter.","definition_pt":"Uma forma variante de um personagem escrito ou letra, como fontes diferentes ou estilos de escrita representando a mesma letra.","example_en":"The letter 'a' in print and cursive are allographs of the same grapheme.","example_pt":"A letra \"A\" em impressão e cursiva são alogramas do mesmo grafema.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"allometric","translation":"alométrico","definition_en":"Describing the relationship between the size of a body part and the size of the whole organism, or between different biological variables, often following a power law.","definition_pt":"Descrevendo a relação entre o tamanho de uma parte do corpo e o tamanho de todo o organismo, ou entre diferentes variáveis biológicas, muitas vezes seguindo uma lei de poder.","example_en":"The allometric scaling of metabolic rate is a key concept in biology.","example_pt":"A escala alométrica da taxa metabólica é um conceito chave na biologia.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"allometry","translation":"alometria","definition_en":"The study of the relationship between the size and growth of a body part and the size and growth of the entire organism.","definition_pt":"O estudo da relação entre o tamanho e o crescimento de uma parte do corpo e o tamanho e crescimento de todo o organismo.","example_en":"Allometry is used to understand how an animal's leg length scales with its body mass.","example_pt":"A alometria é usada para entender como a perna de um animal escala com sua massa corporal.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"allomorph","translation":"alomorfe","definition_en":"A variant phonological representation of a morpheme, which changes based on phonetic context.","definition_pt":"Uma representação fonológica variante de um morfema, que muda baseado no contexto fonético.","example_en":"The plural morpheme in English has allomorphs like /s/, /z/, and /ɪz/.","example_pt":"O morfema plural em inglês tem alomorfos como /s/, /z/, e /z/.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"allopathic","translation":"alopata","definition_en":"Of or relating to the practice of allopathy, which treats disease with remedies that produce effects opposite to the symptoms.","definition_pt":"De ou se relacionar com a prática da alopatia, que trata doenças com remédios que produzem efeitos opostos aos sintomas.","example_en":"The patient chose an allopathic treatment for his infection.","example_pt":"O paciente escolheu um tratamento alopático para a infecção.","cefr_level":"C1","word_type":"adjective","category_slug":"health","frequency_rank":null},
{"word":"allopatric","translation":"alopátrico","definition_en":"Describing biological species or the process of speciation that occurs when populations are separated by a geographic barrier, preventing gene flow.","definition_pt":"Descrevendo espécies biológicas ou o processo de especiação que ocorre quando as populações são separadas por uma barreira geográfica, impedindo o fluxo de genes.","example_en":"Allopatric speciation is often driven by mountain ranges or bodies of water.","example_pt":"Especiação alopátrica é frequentemente conduzida por montanhas ou corpos de água.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"allopatry","translation":"alopatria","definition_en":"The occurrence of related organisms in separate, non-overlapping geographical areas, often leading to speciation.","definition_pt":"A ocorrência de organismos relacionados em áreas geográficas separadas, não-sobrepostas, muitas vezes levando a especiação.","example_en":"Allopatry is a key concept in understanding how new species evolve.","example_pt":"Alopatologia é um conceito chave para entender como novas espécies evoluem.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"allophonic","translation":"alofônico","definition_en":"Relating to or characteristic of allophones, which are variant forms of a single phoneme in a language.","definition_pt":"Relativo ou característico de alofones, que são formas variantes de um único fonema em uma língua.","example_en":"The linguist studied the allophonic variations in different dialects.","example_pt":"O linguista estudou as variações alofônicas em diferentes dialetos.","cefr_level":"C2","word_type":"adjective","category_slug":"technical","frequency_rank":null},
{"word":"allopurinol","translation":"alopurinol","definition_en":"A medication used to lower high levels of uric acid in the blood, primarily to treat gout and prevent kidney stones.","definition_pt":"Um medicamento usado para baixar níveis elevados de ácido úrico no sangue, principalmente para tratar gota e prevenir pedras nos rins.","example_en":"The doctor prescribed allopurinol to manage his chronic gout.","example_pt":"O médico prescreveu alopurinol para controlar sua gota crônica.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"allosaur","translation":"alossauro","definition_en":"A large, bipedal carnivorous dinosaur from the late Jurassic period, similar to but somewhat smaller than Tyrannosaurus rex.","definition_pt":"Um grande dinossauro carnívoro bípede do final do período Jurássico, similar mas um pouco menor que o Tiranossauro Rex.","example_en":"The allosaur was a dominant predator of its time.","example_pt":"O alossauro era um predador dominante de seu tempo.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"allosaurus","translation":"alossauro","definition_en":"A large, bipedal carnivorous dinosaur from the late Jurassic period, known for its powerful jaws and sharp teeth.","definition_pt":"Um grande dinossauro carnívoro bípede do final do período Jurássico, conhecido por suas poderosas mandíbulas e dentes afiados.","example_en":"The allosaurus was one of the top predators of its time.","example_pt":"O alossauro era um dos principais predadores de seu tempo.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"allotrope","translation":"alótropo","definition_en":"One of two or more different physical forms in which an element can exist, differing in the arrangement of atoms.","definition_pt":"Uma de duas ou mais formas físicas diferentes nas quais um elemento pode existir, diferente no arranjo de átomos.","example_en":"Diamond and graphite are allotropes of carbon.","example_pt":"Diamante e grafite são alotropes de carbono.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"allotropic","translation":"alotrópico","definition_en":"Relating to or showing the property of existing in two or more different physical forms, especially of a chemical element.","definition_pt":"Relacionando ou mostrando a propriedade de existir em duas ou mais formas físicas diferentes, especialmente de um elemento químico.","example_en":"Diamond and graphite are allotropic forms of carbon.","example_pt":"Diamante e grafite são formas alotrópicas de carbono.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"allotropy","translation":"alotropia","definition_en":"The property of some chemical elements to exist in two or more different physical forms, known as allotropes.","definition_pt":"A propriedade de alguns elementos químicos para existir em duas ou mais formas físicas diferentes, conhecidas como alótropos.","example_en":"Carbon exhibits allotropy in the forms of diamond and graphite.","example_pt":"Carbono exibe alotropia em formas de diamante e grafite.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"allspice","translation":"pimenta-da-jamaica","definition_en":"A dried berry-like fruit from the Pimenta dioica tree, used as a spice that tastes like a combination of cinnamon, nutmeg, and cloves.","definition_pt":"Uma fruta seca parecida com a fruta da Pimenta dioica, usada como uma especiaria que tem gosto de uma combinação de canela, noz-moscada e cravos.","example_en":"She added a teaspoon of allspice to the pumpkin pie.","example_pt":"Ela adicionou uma colher de chá de pimenta na torta de abóbora.","cefr_level":"B1","word_type":"noun","category_slug":"food","frequency_rank":null},
{"word":"allude","translation":"aludir","definition_en":"To make an indirect reference to something or someone without explicitly naming it.","definition_pt":"Fazer uma referência indireta a algo ou alguém sem nomeá-lo explicitamente.","example_en":"The author alluded to the political situation in his novel.","example_pt":"O autor aludiu à situação política em seu romance.","cefr_level":"C2","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"allusion","translation":"alusão","definition_en":"An expression designed to call something to mind without mentioning it explicitly; an indirect or passing reference.","definition_pt":"Uma expressão que chama algo à mente sem mencionar explicitamente, uma referência indireta ou passageira.","example_en":"The poem contains an allusion to Greek mythology.","example_pt":"O poema contém uma alusão à mitologia grega.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"allusive","translation":"alusivo","definition_en":"Containing or making use of indirect references or hints, often to other works, events, or ideas.","definition_pt":"Contendo ou fazendo uso de referências indiretas ou dicas, muitas vezes para outras obras, eventos ou idéias.","example_en":"Her writing style is highly allusive, often referencing classical mythology.","example_pt":"Seu estilo de escrita é altamente alusivo, muitas vezes referenciando mitologia clássica.","cefr_level":"C1","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"allusiveness","translation":"alusividade","definition_en":"A characteristic of language or writing that makes subtle or indirect references to other works, events, or ideas.","definition_pt":"Uma característica da linguagem ou escrita que faz referências sutis ou indiretas a outras obras, eventos ou idéias.","example_en":"The poet's work is known for its rich allusiveness to classical mythology.","example_pt":"O trabalho do poeta é conhecido por sua rica alusividade à mitologia clássica.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"alluvial","translation":"aluvial","definition_en":"Describing soil, sand, gravel, or other sediment deposited by flowing water, such as rivers or streams.","definition_pt":"Descrevendo solo, areia, cascalho, ou outros sedimentos depositados por água corrente, como rios ou riachos.","example_en":"The alluvial soil in the valley is very fertile for farming.","example_pt":"O solo aluvial no vale é muito fértil para a agricultura.","cefr_level":"C1","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"alluvium","translation":"alúvio","definition_en":"Soil, clay, silt, or gravel that is transported and deposited by flowing water, typically in riverbeds, floodplains, or deltas.","definition_pt":"Solo, argila, lodo ou cascalho que é transportado e depositado por água corrente, tipicamente em leitos de rios, planícies de inundação, ou deltas.","example_en":"The fertile valley was formed by layers of alluvium deposited over centuries.","example_pt":"O vale fértil foi formado por camadas de aluvium depositadas ao longo de séculos.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"allyl","translation":"alila","definition_en":"An unsaturated organic radical with the formula C3H5, derived from propylene, commonly found in compounds like allyl alcohol and allyl chloride.","definition_pt":"Um radical orgânico insaturado com a fórmula C3H5, derivado do propileno, comumente encontrado em compostos como álcool alil e cloreto de alilo.","example_en":"Allyl groups are often used in organic synthesis.","example_pt":"Grupos de alilo são frequentemente usados em síntese orgânica.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"allylic","translation":"alílico","definition_en":"Describing a chemical compound or property that involves the allyl group (CH₂=CH-CH₂-), often characterized by a specific type of reactivity in organic chemistry.","definition_pt":"Descrevendo um composto químico ou propriedade que envolve o grupo alilo (CH2=CH-CH2-), muitas vezes caracterizado por um tipo específico de reatividade em química orgânica.","example_en":"The allylic rearrangement is a key step in the synthesis.","example_pt":"O rearranjo alílico é um passo chave na síntese.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"almandine","translation":"almandita","definition_en":"A deep red to violet-red gemstone variety of garnet, composed of iron aluminum silicate.","definition_pt":"Uma profunda variedade de granada vermelha a vermelha violeta, composta de silicato de alumínio de ferro.","example_en":"The ring was set with a large almandine garnet.","example_pt":"O anel estava com uma granada de almandina grande.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"almsgiver","translation":"esmoler","definition_en":"A person who gives money, food, or other forms of aid to the poor or needy.","definition_pt":"Uma pessoa que dá dinheiro, comida ou outras formas de ajuda aos pobres ou necessitados.","example_en":"The almsgiver distributed food to the homeless shelter.","example_pt":"O doador de esmolas distribuiu comida para o abrigo de sem-teto.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"almsgiving","translation":"esmola","definition_en":"The act of voluntarily giving money, food, or other aid to those in need, often as a religious or moral duty.","definition_pt":"O ato de dar dinheiro, comida ou outra ajuda voluntária aos necessitados, muitas vezes como um dever religioso ou moral.","example_en":"Almsgiving is a central practice in many religious traditions.","example_pt":"A esmola é uma prática central em muitas tradições religiosas.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"alocasia","translation":"alocásia","definition_en":"A plant from the genus Alocasia, known for its large, showy, arrow-shaped leaves and boat-shaped flower spathe, often grown as an ornamental.","definition_pt":"Uma planta do gênero Alocasia, conhecida por suas folhas grandes, vistosas, em forma de flecha e spathe de flores em forma de barco, muitas vezes cultivadas como ornamentais.","example_en":"The alocasia in the corner of the room has grown enormous leaves.","example_pt":"A alocásia no canto da sala cresceu folhas enormes.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"aloofness","translation":"distância","definition_en":"A state of being emotionally distant, reserved, or detached from others.","definition_pt":"Um estado de estar emocionalmente distante, reservado ou desprendido dos outros.","example_en":"His aloofness made it difficult for others to approach him.","example_pt":"Sua indiferença dificultava a aproximação dos outros.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"alopecia","translation":"alopécia","definition_en":"The partial or complete loss of hair from areas of the body where it normally grows, most commonly the scalp.","definition_pt":"A perda parcial ou completa de cabelo de áreas do corpo onde normalmente cresce, mais comumente o couro cabeludo.","example_en":"The patient was diagnosed with alopecia after experiencing sudden hair loss.","example_pt":"O paciente foi diagnosticado com alopecia após ter sofrido queda de cabelo súbita.","cefr_level":"B2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"alopecic","translation":"alopécico","definition_en":"Relating to or characterized by the loss of hair, wool, or feathers from the body.","definition_pt":"Relacionado com ou caracterizado pela perda de cabelo, lã ou penas do corpo.","example_en":"The alopecic patches on his scalp were treated by a dermatologist.","example_pt":"Os adesivos alopécicos no couro cabeludo foram tratados por um dermatologista.","cefr_level":"C1","word_type":"adjective","category_slug":"health","frequency_rank":null},
{"word":"alpenstock","translation":"alpenstock","definition_en":"A long, strong stick with a pointed metal tip, traditionally used by hikers and mountaineers for balance and support on rough terrain.","definition_pt":"Um pau longo e forte com ponta de metal pontudo, tradicionalmente usado por caminhantes e montanhistas para equilibrar e apoiar em terreno áspero.","example_en":"The experienced climber leaned on his alpenstock while crossing the rocky path.","example_pt":"O experiente alpinista se inclinou em seu alpenstock enquanto cruzava o caminho rochoso.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"alpha-blocker","translation":"bloqueador alfa-adrenérgico","definition_en":"A class of drugs that block alpha-adrenergic receptors, used primarily to treat benign prostatic hyperplasia by relaxing the muscles of the prostate and bladder neck.","definition_pt":"Uma classe de drogas que bloqueiam receptores alfa-adrenérgicos, usados principalmente para tratar hiperplasia benigna da próstata e do pescoço da bexiga.","example_en":"The doctor prescribed an alpha-blocker to relieve his urinary symptoms.","example_pt":"O médico prescreveu um alfabloqueador para aliviar os sintomas urinários.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"alphanumeric","translation":"alfanumérico","definition_en":"Consisting of or using letters, numbers, and sometimes other symbols such as punctuation marks.","definition_pt":"Constituindo ou usando letras, números, e às vezes outros símbolos, como marcas de pontuação.","example_en":"The password must be alphanumeric, including both letters and digits.","example_pt":"A senha deve ser alfanumérica, incluindo letras e dígitos.","cefr_level":"B2","word_type":"adjective","category_slug":"technology","frequency_rank":null},
{"word":"alphavirus","translation":"alfavírus","definition_en":"A type of arbovirus belonging to the Togaviridae family, known to cause various forms of encephalitis, particularly in horses.","definition_pt":"Um tipo de arbovírus pertencente à família Togaviridae, conhecido por causar várias formas de encefalite, particularmente em cavalos.","example_en":"The alphavirus was identified as the cause of the recent outbreak of equine encephalitis.","example_pt":"O alfavírus foi identificado como a causa do recente surto de encefalite equina.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"alprazolam","translation":"alprazolam","definition_en":"A medication of the benzodiazepine class used to treat anxiety disorders and panic attacks.","definition_pt":"Um medicamento da classe dos benzodiazepínicos usado para tratar transtornos de ansiedade e ataques de pânico.","example_en":"The doctor prescribed alprazolam for her severe anxiety.","example_pt":"O médico receitou alprazolam para sua ansiedade.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"alstroemeria","translation":"alstroeméria","definition_en":"A type of plant native to South America, known for its attractive clusters of colorful flowers.","definition_pt":"Um tipo de planta nativa da América do Sul, conhecida por seus atraentes aglomerados de flores coloridas.","example_en":"The garden was full of beautiful alstroemeria in shades of pink and orange.","example_pt":"O jardim estava cheio de belas alstroemerias em tons de rosa e laranja.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"altaic","translation":"altaico","definition_en":"Of or pertaining to the proposed language family that includes Turkic, Mongolic, and Tungusic languages, and sometimes Korean and Japanese.","definition_pt":"Ou pertencente à família de idiomas propostos que inclui línguas turcas, mongólicas e tungusicas, e às vezes coreanas e japonesas.","example_en":"The Altaic hypothesis remains a subject of debate among linguists.","example_pt":"A hipótese Altaica continua sendo tema de debate entre linguistas.","cefr_level":"C1","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"altarpiece","translation":"retábulo","definition_en":"A painted or carved panel or screen that is placed above and behind an altar or communion table in a church.","definition_pt":"Um painel ou tela pintado ou esculpido que é colocado acima e atrás de um altar ou mesa de comunhão em uma igreja.","example_en":"The cathedral's altarpiece depicts the Last Supper in vivid detail.","example_pt":"O altar da catedral retrata a Última Ceia em detalhes vívidos.","cefr_level":"C1","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"altazimuth","translation":"altazimute","definition_en":"A telescope mount or instrument that allows rotation around both vertical and horizontal axes, enabling measurement of altitude and azimuth of celestial objects.","definition_pt":"Um telescópio ou instrumento que permite rotação em torno de ambos os eixos verticais e horizontais, permitindo a medição da altitude e azimute de objetos celestes.","example_en":"The astronomer used an altazimuth to track the star's position across the sky.","example_pt":"O astrônomo usou um altazimute para rastrear a posição da estrela através do céu.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"alterability","translation":"alterabilidade","definition_en":"The capacity or ability to be changed, modified, or adjusted.","definition_pt":"A capacidade ou habilidade de ser alterada, modificada ou ajustada.","example_en":"The alterability of the software allows for easy updates.","example_pt":"A alterabilidade do software permite atualizações fáceis.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"alterable","translation":"alterável","definition_en":"Able to be modified or adjusted in some characteristic.","definition_pt":"Capaz de ser modificado ou ajustado em alguma característica.","example_en":"The terms of the contract are alterable with mutual consent.","example_pt":"Os termos do contrato são alteráveis com consentimento mútuo.","cefr_level":"B2","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"alternately","translation":"alternadamente","definition_en":"In a way that involves two or more things happening or existing one after the other repeatedly.","definition_pt":"De uma forma que envolve duas ou mais coisas acontecendo ou existindo uma após a outra repetidamente.","example_en":"The lights flashed alternately red and green.","example_pt":"As luzes piscavam alternadamente vermelho e verde.","cefr_level":"B2","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"alternation","translation":"alternância","definition_en":"The repeated change from one thing or state to another and back again.","definition_pt":"A mudança repetida de uma coisa ou estado para outra e de volta novamente.","example_en":"The alternation of day and night is a natural cycle.","example_pt":"A alternância do dia e da noite é um ciclo natural.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"altostratus","translation":"altostratus","definition_en":"A type of cloud that forms a gray or blue-gray layer at middle altitudes, typically between 2,000 and 7,000 meters (6,500 to 23,000 feet), often covering the entire sky and sometimes producing light precipitation.","definition_pt":"Um tipo de nuvem que forma uma camada cinza ou azul-cinzento em altitudes médias, tipicamente entre 2.000 e 7.000 metros (6.500 a 23.000 pés), muitas vezes cobrindo todo o céu e às vezes produzindo precipitação de luz.","example_en":"The sky was covered by a thick layer of altostratus, blocking out the sun.","example_pt":"O céu estava coberto por uma espessa camada de altostrato, bloqueando o sol.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"altricial","translation":"altricial","definition_en":"Describing young animals that are born or hatched in a relatively undeveloped state, requiring extensive parental care for feeding and protection.","definition_pt":"Descrevendo animais jovens que nascem ou nascem em um estado relativamente pouco desenvolvido, exigindo cuidados parentais extensivos para alimentação e proteção.","example_en":"Altricial birds, such as robins, are born blind and featherless.","example_pt":"Aves altriciais, como os Robins, nascem cegas e sem penas.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"altruist","translation":"altruísta","definition_en":"A person who is motivated by a genuine desire to help others and improve their well-being, often through charitable acts.","definition_pt":"Uma pessoa motivada por um desejo genuíno de ajudar os outros e melhorar seu bem-estar, muitas vezes através de atos de caridade.","example_en":"The wealthy businessman was a true altruist, donating millions to build schools in poor regions.","example_pt":"O empresário rico era um verdadeiro altruísta, doando milhões para construir escolas em regiões pobres.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"altruistically","translation":"altruisticamente","definition_en":"In a way that shows unselfish concern for the welfare of others.","definition_pt":"De uma forma que mostra interesse altruísta pelo bem-estar dos outros.","example_en":"She altruistically donated her entire savings to the charity.","example_pt":"Ela doou todas as suas economias para a caridade.","cefr_level":"C1","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"alumina","translation":"alumina","definition_en":"A white or colorless crystalline compound (Al₂O₃) that occurs naturally as corundum and is used in the production of aluminum and abrasives.","definition_pt":"Um composto cristalino branco ou incolor (Al2O3) que ocorre naturalmente como corindo e é usado na produção de alumínio e abrasivos.","example_en":"Alumina is a key raw material in the manufacturing of aluminum metal.","example_pt":"Alumina é uma matéria-prima chave na fabricação de alumínio metálico.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"aluminate","translation":"aluminato","definition_en":"A salt or compound formed from alumina (aluminum oxide) and a metallic oxide, typically found in minerals or industrial materials.","definition_pt":"Um sal ou composto formado de alumina (óxido de alumínio) e um óxido metálico, tipicamente encontrado em minerais ou materiais industriais.","example_en":"Sodium aluminate is used in water treatment processes.","example_pt":"Aluminato de sódio é usado em processos de tratamento de água.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"alumna","translation":"diplomada","definition_en":"A woman who has graduated from a particular school, college, or university.","definition_pt":"Uma mulher que se formou em uma escola, faculdade ou universidade.","example_en":"She is an alumna of Harvard University.","example_pt":"Ela é uma aluna da Universidade de Harvard.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"alumnus","translation":"graduado","definition_en":"A person who has completed a course of study and received a degree or diploma from a school, college, or university.","definition_pt":"Uma pessoa que completou um curso de estudos e recebeu um diploma de uma escola, faculdade ou universidade.","example_en":"He is an alumnus of Harvard University.","example_pt":"Ele é um ex-aluno da Universidade de Harvard.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"alveolar","translation":"alveolar","definition_en":"Describing a speech sound produced with the tongue tip touching or near the ridge behind the upper front teeth.","definition_pt":"Descrevendo um som de fala produzido com a ponta da língua tocando ou perto da crista atrás dos dentes superiores da frente.","example_en":"The 't' and 'd' sounds in English are alveolar consonants.","example_pt":"Os sons \"t\" e \"d\" em inglês são consoantes alveolares.","cefr_level":"C1","word_type":"adjective","category_slug":"health","frequency_rank":null},
{"word":"alveolate","translation":"alveolado","definition_en":"Describes a surface that is marked with many small, cell-like depressions or pits, resembling a honeycomb.","definition_pt":"Descreve uma superfície que é marcada com muitas pequenas depressões ou fossas, parecidas com uma favo de mel.","example_en":"The alveolate structure of the bone makes it lightweight yet strong.","example_pt":"A estrutura alveolada do osso o torna leve, mas forte.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"alveolitis","translation":"alveolite","definition_en":"Inflammation of the tooth socket, often occurring after a tooth extraction when the blood clot fails to form properly.","definition_pt":"Inflamação da cavidade dentária, ocorrendo frequentemente após uma extração de dentes quando o coágulo não se forma adequadamente.","example_en":"The patient developed alveolitis after the wisdom tooth was removed.","example_pt":"O paciente desenvolveu alveolite após a remoção do dente siso.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"alveolus","translation":"alvéolo","definition_en":"A tiny, balloon-shaped air sac in the lungs where the exchange of oxygen and carbon dioxide takes place.","definition_pt":"Um pequeno saco de ar em forma de balão nos pulmões onde ocorre a troca de oxigênio e dióxido de carbono.","example_en":"The alveoli are responsible for transferring oxygen into the bloodstream.","example_pt":"Os alvéolos são responsáveis pela transferência de oxigênio para a corrente sanguínea.","cefr_level":"B2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"alyssum","translation":"alisso","definition_en":"A type of garden plant from the genus Alyssum, known for its clusters of small, fragrant yellow or white flowers.","definition_pt":"Um tipo de planta de jardim do gênero Alyssum, conhecido por seus cachos de pequenas flores amarelas ou brancas perfumadas.","example_en":"She planted alyssum along the edge of the flower bed.","example_pt":"Ela plantou alyssum ao longo da borda do canteiro de flores.","cefr_level":"B1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"amalgam","translation":"amálgama","definition_en":"A mixture of mercury with another metal, typically silver, used in dentistry to repair cavities in teeth.","definition_pt":"Uma mistura de mercúrio com outro metal, tipicamente prata, usado na odontologia para reparar cavidades nos dentes.","example_en":"The dentist used an amalgam to fill the cavity.","example_pt":"O dentista usou uma amálgama para preencher a cavidade.","cefr_level":"B2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"amalgamate","translation":"amalgamar","definition_en":"To bring together or combine separate elements into a unified whole.","definition_pt":"Reunir ou combinar elementos separados em um todo unificado.","example_en":"The two companies decided to amalgamate to increase their market share.","example_pt":"As duas empresas decidiram se fundir para aumentar sua quota de mercado.","cefr_level":"C1","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"amalgamated","translation":"amalgamado","definition_en":"Joined together to form a single, unified whole.","definition_pt":"Juntos para formar um único, unificado todo.","example_en":"The two companies became an amalgamated corporation after the merger.","example_pt":"As duas empresas se tornaram uma corporação amalgamada após a fusão.","cefr_level":"B2","word_type":"adjective","category_slug":"business","frequency_rank":null},
{"word":"amalgamation","translation":"amálgama","definition_en":"The act of combining or uniting multiple things into one whole.","definition_pt":"O ato de combinar ou unir várias coisas em um só todo.","example_en":"The new dish was an amalgamation of flavors from different cuisines.","example_pt":"O novo prato foi uma mistura de sabores de diferentes cozinhas.","cefr_level":"B2","word_type":"noun","category_slug":"business","frequency_rank":null},
{"word":"amanuensis","translation":"amanuense","definition_en":"A person who is skilled at writing down what someone else says, especially from dictation.","definition_pt":"Uma pessoa que é habilidosa em escrever o que alguém diz, especialmente de ditados.","example_en":"The professor dictated his research notes to his amanuensis.","example_pt":"O professor ditava suas notas de pesquisa para seu amanuensis.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"amaranth","translation":"amaranto","definition_en":"The small, nutritious seed of amaranth plants, used as a grain-like food source, especially in Central and South America.","definition_pt":"A pequena semente nutritiva de plantas de amaranto, usada como fonte de alimento, especialmente na América Central e do Sul.","example_en":"Amaranth is often cooked like porridge or popped like popcorn.","example_pt":"Amaranto é frequentemente cozido como mingau ou estourado como pipoca.","cefr_level":"B2","word_type":"noun","category_slug":"food","frequency_rank":null},
